import React from 'react';
import useScreenSize from "../../hooks/useScreenSize";
import WebVideoCall from "../WebVideoCall/WebVideoCall";
import MobileVideoCall from "../MobileVideoCall/MobileVideoCall";



function VideoCall(props) {
    return (
        useScreenSize().width > 450 ? (
            <WebVideoCall/>
        ) : (
            <MobileVideoCall/>
        )
    );
}

export default VideoCall;